"""Resource refusals of the attention backward main kernel.

Family glue (Python-only, no C++ twin). A few default-off knob combinations
compile, on the production compiler, to a code object that fails the
backward resource gate (scratch, VGPR or SGPR spills, or AGPR copies in a
hot q loop above the ceiling), or crash the code-object compiler itself.
Each such combination was found by compiling every resource-gate row of the
backward tests (the IR suite's instances and knob instances, the knob value
sets on each target's default tiles, the schedule values over the gate
variants, the counted-wait and mirror-pairing rows and their twins, the
main kernels the device tests of those levers and of the composition sets
launch) with the production compiler; :data:`RESOURCE_REFUSED` lists
exactly the resolved specs that failed, and the validator refuses them, so
the sweep never compiles them and every remaining row passes the gate.

A refused spec is identified by :func:`spec_digest`: a digest of its arch and
of every resolved field that differs from its declared default (so adding a
new defaulted field does not move a digest). Two specs with the same digest
emit the same kernel, so the refusal is exact: it refuses no other kernel.
The test suite pins each entry to the gate row it came from.
"""

from __future__ import annotations

import hashlib
from dataclasses import MISSING, fields
from types import MappingProxyType
from typing import Any

__all__ = ["RESOURCE_REFUSED", "resource_refusal", "spec_digest"]


def spec_digest(spec: Any, arch: str) -> str:
    """16 hex digits over ``arch`` and the non-default resolved fields of
    ``spec`` (``name`` excluded)."""
    items = []
    for f in fields(spec):
        if f.name == "name":
            continue
        value = getattr(spec, f.name)
        if f.default is MISSING or value != f.default:
            items.append((f.name, value))
    blob = f"{arch}|{sorted(items)!r}"
    return hashlib.sha256(blob.encode()).hexdigest()[:16]


